import java.util.HashSet;
import java.util.Set;

public class ImmutableSetPattern {
    // Solution: Immutable Java record guarantees hash stability forever
    public record AccountKey(String accountId, String branchCode) {
        public AccountKey {
            if (accountId == null || branchCode == null) {
                throw new IllegalArgumentException("Fields cannot be null");
            }
        }
    }

    public static void main(String[] args) {
        Set<AccountKey> verifiedAccounts = new HashSet<>();
        AccountKey key = new AccountKey("ACC-101", "NYC-01");

        verifiedAccounts.add(key);
        System.out.println("Account registered: " + verifiedAccounts.contains(key));

        // Records cannot be mutated! No setters exist.
        // verifiedAccounts invariants are permanently guaranteed.
        System.out.println("Vault integrity secure. Active accounts: " + verifiedAccounts.size());
    }
}

