import java.util.Set;

public class VanishingRecovery {
    public static class Account {
        public String id;
        public double balance;
        public Account(String id, double balance) { this.id = id; this.balance = balance; }
        public boolean equals(Object o) {
            if (!(o instanceof Account a)) return false;
            return id.equals(a.id) && balance == a.balance;
        }
        public int hashCode() { return id.hashCode() + (int)balance; }
    }

    public static Account recover(Set<Account> set, String targetId) {
        if (set == null || targetId == null) return null;
        for (Account a : set) {
            if (targetId.equals(a.id)) return a;
        }
        return null;
    }
}

