import java.util.Set;
import java.util.HashSet;
import java.util.Map;
import java.util.HashMap;

public class SetSanitizer {
    public static Set<Product> sanitize(Set<Product> dirtySet) {
        if (dirtySet == null) return new HashSet<>();
        Map<String, Product> uniqueSkuMap = new HashMap<>();
        for (Product p : dirtySet) {
            if (p != null) {
                // Keep the first product seen for this SKU
                uniqueSkuMap.putIfAbsent(p.getSku(), p);
            }
        }
        return new HashSet<>(uniqueSkuMap.values());
    }
}
